svg.script:
/**/
/*
 * width/height="100%" on the foreignObject tracks the viewport on its own, so
 * there is normally nothing to do here. Some engines have historically ignored
 * percentage sizing on foreignObject, so this checks once after load and only
 * falls back to stamping pixels if the box did not actually fill. Stamping
 * unconditionally is what broke this before: it froze the box at whatever the
 * window happened to be at load, and the content was clipped after any resize.
 */
(function () {
	var fo = document.querySelector("foreignObject");
	if (!fo) return;

	function fills() {
		var r = fo.getBoundingClientRect();
		return Math.abs(r.width - window.innerWidth) < 2 && Math.abs(r.height - window.innerHeight) < 2;
	}

	function stamp() {
		fo.setAttribute("width", window.innerWidth);
		fo.setAttribute("height", window.innerHeight);
	}

	window.addEventListener("load", function () {
		if (fills()) return;
		stamp();
		window.addEventListener("resize", stamp);
	});
})();
/**/
